 data security/compliance risks in government/rural settings with large enrollments. The solution is a mobile-first ERP with role-based access, real-time notifications/updates, smart auto-certificates/grading/scheduling/document management, personalized AI assistance, standalone secure per-campus cloud storage, local language support, and free customizable school websites to streamline operations and reduce manual efforts.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"rejected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"CEDAU-10","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"Ed-Tech","domainTags":"SaaS, EdTech, EV / Mobility, App Development / Software","session":"S8","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/1GpS3lq2AUHyhjevALarZz2JiP0aXoCf6/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/1GpS3lq2AUHyhjevALarZz2JiP0aXoCf6/edit?usp=sharing&ouid=1042