r’s solution is a research-validated, 100% herbal polyherbal intimate wash formulated with ingredients such as curcumin and neem to maintain natural pH balance and provide antimicrobial protection. Clinically validated and affordably priced at ₹195, the product aims to improve intimate hygiene awareness, increase accessibility in Tier 2 and Tier 3 markets, and support healthier outcomes for women.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"pending","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"cedau-41","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"consumables","domainTags":"Bio Tech, Consumables","session":"S6","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/17jQg9XR0LqRPj3eRC3a4YTSCC34bS2xC/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/17jQg9XR0LqRPj3eRC3a4YTSCC34bS2xC/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true","documents":[],"not