 response across 62 service categories. Revenue comes from a per-completed-lead commission, scaling toward category-based pricing, priority subscriptions, and enterprise contracts. Its roadmap adds AI-based technician matching, chatbot support, lead prioritization, fraud detection, and demand forecasting. Tamil Nadu represents a large addressable market of independent local service professionals across its 38 districts.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"pending","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"CEDAU-51","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"SaaS","domainTags":"AI / ML, SaaS, ecommerce , App Development / Software","session":"S2","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/1XuDjadqAkzk4-vE3pLzlhAgVZAATO4Mz/edit?usp=drive_link&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/1XuDjadqAkzk4-vE3pLzlhAgVZAATO4Mz/edit?usp=drive_link&ouid=1042772