. Its edge lies in the compact, modular, scalable design combined with ML-driven faster crop cycles and full automation, unlike existing hydroponic systems that are costly and manually monitored. Grant funds will cover prototype fabrication, IoT integration, testing, and patent filing. Market research is included as a line item.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"pending","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"CEDAU-54","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"Enviro-Tech","domainTags":"AgriTech, IoT / Hardware, Automation","session":"S5","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://drive.google.com/file/d/1MZmmKsUva2j60JwGRRjdJHdHuwsOg9eV/view?usp=drive_link"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://drive.google.com/file/d/1MZmmKsUva2j60JwGRRjdJHdHuwsOg9eV/view?usp=drive_link","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Exc