ots is missing and large tractors are inaccessible. It''s a compact, lightweight, all-terrain machine built for narrow, water-filled paddy fields, controlled remotely via an ESP32–BTS7960 system for easy use by elderly and marginal farmers. Its modular design supports eight detachable implements (leveller, bed former, bund shaper, ploughers, mud block remover) on a single chassis, replacing multiple separate tools. Running solely on solar power, it cuts fuel and maintenance costs, with expansion potential into Bangladesh, Nepal, and Africa''s comparable marginal-farming markets.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"rejected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"IPO-7i7nb","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"Agri-Tech","domainTags":"AgriTech, Enviro Tech, IoT / Hardware","session":"S4","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://drive.google.com/file/d/1P71FvYpItc1HA5flnMDZjHqgEnahKtvC/view?usp=sharing"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://