g 100% rat-proofing, long-lasting reusability (up to 3 years), waterproofing, and airflow preservation without chemicals or toxins, outperforming sprays, meshes, and ultrasonic devices.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":200000,"stage":"grant","status":"selected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":true,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"SC-591xv","teamSize":1,"linkedin":"","collegeLinkedin":"","domain":"Consumables","domainTags":"SaaS, Consumables, Enviro Tech","session":"S6","startupRegistered":"Pvt Ltd"},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"Pvt Ltd","pitchLink":"https://docs.google.com/presentation/d/1if-EUnplBW5VbKgR7L12TzrIzz_2XseW/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":200000,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/1if-EUnplBW5VbKgR7L12TzrIzz_2XseW/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"grant","remark