igh Gradeability Drivetrain (torque-biased diffs/low gearing/traction control/lightweight chassis for steep climbs); Rollover Detection & Safe Shutdown (tilt/traction-loss auto-cutoff); Terrain-Based Adaptive Suspension (servo-adjusted FOX shocks via sensors); and Topology-Optimized Steering Knuckle (30% lighter AlSi10Mg 3D-printed via FEA for better handling/efficiency).","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":297000,"stage":"grant","status":"selected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"cedau-11","teamSize":135,"linkedin":"","collegeLinkedin":"","domain":"Auto ; EV","domainTags":"Hardware, Automobiles","session":"S5","startupRegistered":"-"},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/1EV9T72VDcsImuuEu7YDiejbpGu0Mvy9q/edit?usp=drive_link&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":297000,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/1EV9T72VDcsImuuEu7YDiejbpGu0Mvy9q/edit?usp=drive_link&ouid=104277249549708518105&rtpof=true&sd=true","documents":[],"notes":[],"created