MVP launch with a lean but structured 6‑month financial roadmap covering app store setup, cloud infrastructure, initial inventory, local delivery, and performance marketing, using a hybrid inventory-plus-commission model and phased logistics to reach profitabi","problemStatement":"This fashion-tech marketplace targets Chennai’s Pondy Bazaar shoppers and local boutiques by building a mobile-first platform that curates inventory and partners with neighborhood vendors to bring their catalog online. The venture plans an MVP launch with a lean but structured 6‑month financial roadmap covering app store setup, cloud infrastructure, initial inventory, local delivery, and performance marketing, using a hybrid inventory-plus-commission model and phased logistics to reach profitability within an 8.5 lakh runway while scaling vendor participation","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"pending","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"Sc-3343hr","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"Fashion","domainTags":"E-Commerce, Fashion / Lifestyle, App Development / Software","session":"S6","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://drive.google.com/file/d/1JpesebGrTQRjlE59-oIm47tqykoWEbXQ/view?usp=sharing"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://drive.google.com/file/d/1JpesebGrTQRjlE59-oIm47tqykoWEbXQ/view?usp=sharing","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"registration","remarks":"Batch 2025-26"}]},{"applicationId":"GRT-2026-27-090","applicantName":"Sharvesh S","phone":"6369766990","email":"sharvesh4705@gmail.com","memberId":null,"teamId":"PX-x22sud","type":"individual","batch":"2025-26","gender":"Male","caste":"","tier":"Tier 2","college":"PSG Institute of Technology and Applied Research","womenBeneficiaries":0,"ideaName":"Sun-dram Technologies","sector":"Deep Tech","industry":"Deep Tech","ideaDescription":"SUN-DRAM by Sun-dram Technologies addresses the vulnerability of classical encryption (RSA, ECC) used in HTTPS/TLS/SSL certificates securing billions of websites, which quantum computers can break via methods like Shor''s algorithm, risking massive data breaches. With 250,000 new websites created daily and no easy upgrade paths to Post-Quantum Cryptography (PQC), organizations face \"harvest now, decrypt later\" threats from qubit attacks. The solution offers India''s first plug-and-play PQC Web Sec","problemStatement":"SUN-DRAM by Sun-dram Technologies addresses the vulnerability of classical encryption (RSA, ECC) used in HTTPS/TLS/SSL certificates securing billions of websites, which quantum computers can break via methods like Shor''s algorithm, risking massive data breaches. With 250,000 new websites created daily and no easy upgrade paths to Post-Quantum Cryptography (PQC), organizations face \"harvest now, decrypt later\" threats from qubit attacks. The solution offers India''s first plug-and-play PQC Web Security API using NIST-approved Kyber (key exchange) and Dilithium (signatures), enabling zero-downtime quantum-safe TLS certificates via simple developer APIs, dashboard, and hybrid engine compatible with existing infrastructure.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":300000,"stage":"grant","status":"selected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"PX-x22sud","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"Deep-Tech","domainTags":"SaaS, AgriTech, Cybersecurity, Deep Tech","session":"S3","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://drive.google.com/file/d/1-yznzjE283jjx-b3vDiIbIwsga68hIlk/view?usp=sharing"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":300000,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://drive.google.com/file/d/1-yznzjE283jjx-b3vDiIbIwsga68hIlk/view?usp=sharing","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"grant","remarks":"Batch 2025-26"}]},{"a