ntName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":""},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"registration","remarks":"Batch 2026-27"}]},{"applicationId":"GRT-2026-27-098","applicantName":"Mohammed Hussain Basith","phone":"7200326094","email":"mohammedhussainbasithsa@gmail.com","memberId":null,"teamId":"SC-83s9eo","type":"individual","batch":"2025-26","gender":"","caste":"","tier":"","college":"Madras Institute of Technology, Chromepet","womenBeneficiaries":0,"ideaName":"OCEAN WAVE ENERGY CONVERTER","sector":"Renewable Energy","industry":"Renewable Energy","ideaDescription":"Over 600 million people globally rely on diesel for electricity, while solar and wind struggle to deliver consistent power in coastal communities. The Ocean Wave Energy Converter (OWEC) solves this through a buoyant HDPE drum with a direct mechanical power take-off system (gears, pulleys, shafts) converting wave motion directly into electricity via a DC generator, eliminating complex hydraulics, offering low-cost corrosion-resistant design, modular scalability from 1kW to 100kW+, high reliabilit","problemStatement":"Over 600 million people globally rely on diesel for electricity, while solar and wind struggle to deliver consistent power in coastal communities. The Ocean Wave Energy Converter (OWEC) solves this through a buoyant HDPE drum with a direct mechanical power take-off system (gears, pulleys, shafts) converting wave motion directly into electricity via a DC generator, eliminating complex hydraulics, offering low-cost corrosion-resistant design, modular scalability from 1kW to 100kW+, high reliability in saltwater environments, silent eco-friendly operation with zero emissions, and 90% wave availability delivering predictable baseload power for off-grid coastal communities and islands.​","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"rejected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"SC-83s9eo","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"Renewable Energy","domainTags":"Enviro Tech","session":"S5","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/1XXOdoM72D_hhdWkD5i29TjW9-amrFpOE/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/1XXOdoM72D_hhdWkD5i29TjW9-amrFpOE/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"registration","remarks":"Batch 2025-26"}]},{"applicationId":"GRT-2026-27-099","applicantName":"Kochadaimuthaiya","phone":"7092922565","email":"","memberId":null,"teamId":"cedau-18","type":"team","batch":"2025-26","gender":"","caste":"","tier":"","college":"EDII-TN","womenBeneficiaries":0,"ideaName":"giggers","sector":"SaaS","industry":"SaaS","ideaDescription":"GIGGERS is a B2B gig workforce platform connecting verified gig workers with verified employers across marketing, events, cine field, seasonal work, and survey categories. Addressing fragmented hiring through informal WhatsApp groups, payment delays, safety risks (especially for women), and lack of transparency, GIGGERS introduces KYC/GST-verified employers, KYC-verified workers, real-time work tracking, area-specific job allocation, SOS safety features, basic insurance, assured payments, and ra","problemStatement":"GIGGERS is a B2B gig workforce platform connecting verified gig workers with verified employers across marketing, events, cine field, seasonal work, and survey categories. Addressing fragmented hiring through informal WhatsApp groups, payment delays, safety risks (especially for women), and lack of transparency, GIGGERS introduces KYC/GST-verified employers, KYC-verified workers, real-time work tracking, area-specific job allocation, SOS safety features, basic insurance, assured payments, and rating systems. With a 6–8% commission model, the platform is validated through 100-day gig economy data (₹1+ crore transactions) and LOIs from employers. GIGGERS aims to formalize gig employment, promote gender equality (SDG 5), and drive economic growth (SDG 8).","proposedSolution":"","businessM