inkedin":"","domain":"MAaaS","domainTags":"","session":"","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":""},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"registration","remarks":"Batch 2026-27"}]},{"applicationId":"GRT-2026-27-102","applicantName":"Tharani P S","phone":"7200939492","email":"pstharani.2004@gmail.com","memberId":null,"teamId":"SC-8s2knl","type":"individual","batch":"2025-26","gender":"Male","caste":"OBC","tier":"Tier 1","college":"St. Joseph''s College of Engineering , OMR, Chennai.","womenBeneficiaries":0,"ideaName":"Auronox Private Limited","sector":"Deep-Tech","industry":"Deep-Tech","ideaDescription":"Emergencies in remote areas face critical delays due to poor connectivity and lack of reliable automation, with 56.07% of accidents occurring on national/state highways, 61.57% in rural areas, and 64.84% being fatal or grievously injurious according to MoRTH 2022 data. AERSVS GEN (Automatic Emergency Response System via Satellite) solves this through a satellite-enabled device in vehicles that auto-detects impacts via crash/health sensors, transmits GPS data to satellite ground stations, and tri","problemStatement":"Emergencies in remote areas face critical delays due to poor connectivity and lack of reliable automation, with 56.07% of accidents occurring on national/state highways, 61.57% in rural areas, and 64.84% being fatal or grievously injurious according to MoRTH 2022 data. AERSVS GEN (Automatic Emergency Response System via Satellite) solves this through a satellite-enabled device in vehicles that auto-detects impacts via crash/health sensors, transmits GPS data to satellite ground stations, and triggers multi-channel SOS alerts (SMS, voice) to first responders and contacts via GEN server, with a mobile app for telematics viewing—ensuring seamless connectivity anywhere without cellular networks.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"rejected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"SC-8s2knl","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"Deep-Tech","domainTags":"IoT / Hardware, EV / Mobility, App Development / Software, Deep Tech, Robotics / Automation","session":"S3","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/1Rbchip-rj68Va3SjmYraQyLPBDxUK_cI/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/1Rbchip-rj68Va3SjmYraQyLPBDxUK_cI/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"registration","remarks":"Batch 2025-26"}]},{"applicationId":"GRT-2026-27-103","applicantName":"Jeziel Praise Son","phone":"9042871766","email":"mjeziel18@gmail.com","memberId":null,"teamId":"SC-9a9rgd","type":"individual","batch":"2025-26","gender":"Male","caste":"OBC","tier":"Tier 2","college":"RVS Educational Trust''s Group of Institutions","womenBeneficiaries":0,"ideaName":"TrustIT","sector":"deep-Tech","industry":"deep-Tech","ideaDescription":"Device repair in India is fragmented and untrustworthy, with over 70% of users facing repair issues due to unreliable providers, inconsistent service quality, lack of standardization, and absence of transparent pricing and quality control, affecting students, professionals, and the elderly nationwide. The unorganized repair sector lacks a centralized, trustworthy solution. TrustIT''s platform addresses this with AI-powered diagnostics using voice and image analysis for precise fault detection, ve","problemStatement":"Device repair in India is fragmented and untrustworthy, with over 70% of users facing repair issues due to unreliable providers, inconsistent service quality, lack of standardization, and absence of transparent pricing and quality control, affecting students, professionals, and the elderly nationwide. The unorganized repair sector lacks a centralized, trustworthy solution. TrustIT''s platform addresses this with AI-powered diagnostics using voice and image analysis for precise fault detection, verified and trained service centers, seamless logistics with pickup/drop and real-time tracking, transparent centralized dashboards showing pricing and repair status, and multilingual UI/UX built on TensorFlow.js, React, Node.js, and Firebase—promoting e-waste reduction and circular economy while creating local employment opportunities through standardized, accessible repair services across India.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"rejected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"SC-9a9rgd","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"deep-Tech","domainTags":"AI / ML, SaaS, App Development / Software","session":"S3","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/149HppxiF5fWSdC5NDButuJX_m6yEKHIP/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/149HppxiF5fWSdC5NDButuJX_m6yEKHIP/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"registration","remarks":"Batch 2025-26"}]},{"applicationId":"GRT-2026-27-104","applicantName":"Anjanarangarajan","phone":"9790339415","email":"anjanarangarajan06@gmail.com","memberId":null,"teamId":"SC-9au7v","type":"individual","batch":"2025-26","gender":"Female","caste":"General","tier":"Tier 3","college":"St. Joseph''s College of Engineering , OMR, Chennai.","womenBeneficiaries":0,"ideaName":"Nova AI","sector":"ai","industry":"ai","ideaDescription":"NOVA AI addresses industrial hazards in chemical manufacturing MSMEs like those in Sivakasi, where manual monitoring fails to detect early gas leaks, thermal hotspots, and machine stress, leading to frequent fires, toxic exposures, and equipment failures. India reports 48,000+ factory accidents and 6,500+ fatalities (2017-2021), with Tamil Nadu among the top states and Sivakasi fireworks seeing 500+ fires, 300+ deaths over 10 years; 80% of factories lack real-time safety systems costing ₹50,000+","problemStatement":"NOVA AI addresses industrial hazards in chemical manufacturing MSMEs like those in Sivakasi, where manual monitoring fails to detect early gas leaks, thermal hotspots, and machine stress, leading to frequent fires, toxic exposures, and equipment failures. India reports 48,000+ factory accidents and 6,500+ fatalities (2017-2021), with Tamil Nadu among the top states and Sivakasi fireworks seeing 500+ fires, 300+ deaths over 10 years; 80% of factories lack real-time safety systems costing ₹50,000+ per node. The solution is an edge AI-powered multi-sensor system (thermal, gas, vibration, vision on Jetson Nano) for real-time hazard detection, automated shutdowns/ventilation, predictive maintenance, PPE compliance, and reports—all offline at ₹18-25k per modular node, 30-50% cheaper via local processing without cloud fees.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"rejected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"SC-9au7v","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"ai","domainTags":"AI / ML, IoT / Hardware","session":"S1","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://drive.google.com/file/d/1YWnN75jWtxNAdKR8L3b7q3YvrpJshX1-/view?usp=sharing"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://drive.google.com/file/d/1YWnN75jWtxNAdKR8L3b7q3YvrpJshX1-/view?usp=sharing","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"registration","remarks":"Batch 2025-26"}]},{"applicationId":"GRT-2026-27-105","applicantName":"Deepika","phone":"7395956159","email":"deepikaharigovindan@gmail.com","memberId":null,"teamId":"SC-qtithv","type":"team","batch":"2025-26","gender":"","caste":"","tier":"","college":"Sri Sairam Homoeopathy Medical College and Research Centre","womenBeneficiaries":2,"ideaName":"Diatech","sector":"MedTech","industry":"MedTech","ideaDescription":"Peripheral neuropathy silently affects 50%+ of India''s 100M+ diabetics, particularly in rural (50M+) and semi-urban areas where every 1 in 2 diabetics is at risk, with no early warning symptoms (numbness, burning pain, foot ulcers) until it''s too late, and existing tools like expensive VibraSense, NeuroTouch, digital/analog biothesiometers are costly, non-portable, and inaccessible even in cities. Neurotronix''s Diatec-D is a portable, affordable, app-guided smart diagnostic device for early non-","problemStatement":"Peripheral neuropathy silently affects 50%+ of India''s 100M+ diabetics, particularly in rural (50M+) and semi-urban areas where every 1 in 2 diabetics is at risk, with no early warning symptoms (numbness, burning pain, foot ulcers) until it''s too late, and existing tools like expensive VibraSense, NeuroTouch, digital/analog biothesiometers are costly, non-portable, and inaccessible even in cities. Neurotronix''s Diatec-D is a portable, affordable, app-guided smart diagnostic device for early non-invasive neuropathy detection, featuring a compact prototype (81x38mm) with motor, sensors, and mobile app integration for patient data entry (name, age, diabetes duration, ulcer history), outperforming expensive/non-portable alternatives through its accessible design targeting government PHCs, diabetic NGOs, hospitals, and clinics amid a global diabetic population of 537M where half develop neuropathy.​","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":300000,"stage":"grant","status":"selected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"SC-qtithv","tea