l without expensive hardware","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":300000,"stage":"grant","status":"selected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"CEDAU-33","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"ai","domainTags":"AI / ML,  Fashion , App Development / Software","session":"S1","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://drive.google.com/file/d/1fzGMOVP8oCSnj7eaLmstMJs_p2Kp5jbl/view?usp=sharing"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":300000,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://drive.google.com/file/d/1fzGMOVP8oCSnj7eaLmstMJs_p2Kp5jbl/view?usp=sharing","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"grant","remarks":"Batch 2025-26"}]},{"applicationId":"GRT-2026-27-116","applicantName":"Armaan Patnaik","phone":"8939077434","email":"reachoutarmaan@gmail.com","memberId":null,"teamId":"SC-eanbmk","type":"individual","batch":"2025-26","gender":"Male","caste":"General","tier":"Tier 1","college":"Madras Institute of Technology, Chromepet","womenBeneficiaries":0,"ideaName":"FIOXYY-NEURAGENT","sector":"ai","industry":"ai","ideaDescription":"Employees spend 2+ hours daily searching for right documents and information within them, with 60% affected and legal, healthcare, manufacturing sectors facing critical knowledge retrieval issues due to disorganized enterprise data and scattered information sources leading to ineffective search performance and unreliable content retrieval. Neuragent is a cloud-native SaaS platform combining neural semantic search and RAG-LLM pipelines with multi-tenant vector database management using FAISS for ","problemStatement":"Employees spend 2+ hours daily searching for right documents and information within them, with 60% affected and legal, healthcare, manufacturing sectors facing critical knowledge retrieval issues due to disorganized enterprise data and scattered information sources leading to ineffective search performance and unreliable content retrieval. Neuragent is a cloud-native SaaS platform combining neural semantic search and RAG-LLM pipelines with multi-tenant vector database management using FAISS for similarity search, transformer-based embeddings for semantic understanding, RESTful APIs for enterprise integration, and real-time document indexing. The solution delivers 5x higher accuracy than legacy keyword-based systems with context-aware, generative AI responses, 99.9% uptime enterprise-grade security, and ROI within 6 months targeting 10,000+ enterprises across legal, healthcare, manufacturing sectors.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"rejected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"SC-eanbmk","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"ai","domainTags":"A