, reducing the 30%+ wastage of home-grown produce while giving nearby households affordable organic options. The platform adds value through traceability, location-based matching, in-app communication, aggregation support, and awareness campaigns, delivering social impact by cutting food waste, strengthening local green economies, and encouraging chemical-free urban farming.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"grant","status":"selected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"sc-529ofg","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"SaaS","domainTags":"AgriTech, E-Commerce","session":"S2","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/1FXfUyGDlWBSVSWdlR8txzdfGM1uWDNfg/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/1FXfUyGDlWBSVSWdlR8txzdfGM1uWDNfg/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true","documents":[],"notes":[],"createdDate":"2026-09-17","l