ctrotherapy, delivering continuous, hands-free, app-controlled pain relief during daily activities.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"pending","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"SC-os5t2w","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"Med-Tech","domainTags":"Consumables , Bio Tech, Sports Tech","session":"S7","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/1qyALgLmfBGwRQZVtXpNxFVOCOLST_2BK/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/1qyALgLmfBGwRQZVtXpNxFVOCOLST_2BK/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true","documents":[],"notes":[],"createdDate":"2026-09-17","lastUpdated":"2026-09-17","history":[{"date":"2026-09-17","time":"12:00","user":"System","action":"Imported from CED Excel","from":"","to":"registration","remarks":"Batch 2025-26"}]},{"applicationId":"GRT-2026-27-134","applicantName":"Saravanan","phone":"9791005395","email":"-","memberId":null,"teamId":"GP-003","type":"team","batch":"2025-26","gender":"","caste":"","tier":"Tier 1","college":"Faculty, CEG","womenBeneficiaries":2,"ideaName":"Animal Tradex","sector":"SAAS","industry":"SAAS","ideaDescription":"AnimalTradeX targets India''s fragmented, unorganized livestock trading system where farmers lack market access and pricing transparency, buyers face health and fraud risks, middlemen manipulate prices, and there is no animal record-keeping or standardized pricing, leaving both farmers and traders vulnerable to exploitation and significant financial losses. AnimalTradeX proposes an AI-powered mobile marketplace with image-based health scanning via computer vision, unique muzzle recognition for fr","problemStatement":"AnimalTradeX targets India''s fragmented, unorganized livestock trading system where farmers lack market access and pricing transparency, buyers face health and fraud risks, middlemen manipulate prices, and there is no animal record-keeping or standardized pricing, leaving both farmers and traders vulnerable to exploitation and significant financial losses. AnimalTradeX proposes an AI-powered mobile marketplace with image-based health scanning via computer vision, unique muzzle recognition for fraud prevention, digital livestock profiles with health and ownership history, real-time mandi pricing, escrow-secured payments, and multilingual support designed specifically for rural and semi-urban farmers, enabling transparent, trustworthy, and scalable livestock e-commerce","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":300000,"stage":"grant","status":"selected","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":true,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"GP-003","teamSize":2,"linkedin":"https://www.linkedin.com/in/saravanan-krishnan-26373b5/","collegeLinkedin":"","domain":"ai"