martwatches and reactive panic buttons. The solution is AlertCare, a low-cost, proactive care ecosystem built around a simple wrist wearable that continuously tracks key vitals and uses an offline, regional-language intelligent voice engine to give real-time spoken guidance to elders without needing smartphones or internet, supported by an AI caregiver app and a grant-backed plan to build and test pilot units for commercialization.","proposedSolution":"","businessModel":"","expectedImpact":"","fundingRequested":0,"stage":"registration","status":"pending","bootcamp":{"attended":true,"date":"","remarks":""},"data":{"consentLetter":false,"fundingTemplate":false,"msmeRegistered":false,"msmeNumber":"","status":"pending","submittedDate":"","teamId":"SC-slpbfe","teamSize":0,"linkedin":"","collegeLinkedin":"","domain":"Health-Tech","domainTags":"Bio Tech, App Development / Software","session":"S7","startupRegistered":""},"rounds":{},"finalEval":{"status":"pending","decision":"","remarks":"","date":""},"edi":{"status":"not_submitted","grantReviewAppId":"","decisionDate":"","remarks":""},"bank":{"accountName":"","accountNumber":"","bankName":"","ifscCode":"","branch":""},"registration":{"udyamNumber":"","gstNumber":"","panNumber":"","registrationType":"","pitchLink":"https://docs.google.com/presentation/d/1k_R53bveQiXpAf_kiNbuGUvDcY5O-ZEo/edit?usp=sharing&ouid=104277249549708518105&rtpof=true&sd=true"},"grant":{"approvalDate":"","sanctionLetterNo":"","approvedAmount":0,"grantType":"Grant Fund","bankVerification":"Pending","agreementStatus":"Pending","phase1":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase2":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""},"phase3":{"amount":0,"eligibleAmount":0,"releaseDate":"","status":"pending","refNumber":"","remarks":""}},"pitchLink":"https://docs.google.com/presentation/d/1k_R53bveQiXpAf_kiNbuGUvDcY5O-ZEo/edit?usp=sharing&ouid=1042772495